// Verify the HMAC-SHA256 signature Convex put on this webhook.
// Convex signs the exact JSON string it POSTs; n8n's JSON parser preserves
// key order, so re-serialising the parsed body reproduces the signed bytes.
// If this n8n version exposes the untouched raw body (Webhook node option
// "Raw Body" is ON), it is preferred via json.rawBody.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment.');

const data = $input.first().json;
const headers = data.headers || {};
const headerValue = headers['x-lendloop-signature'] || '';
const provided = headerValue.replace(/^sha256=/, '').toLowerCase();
const rawBody = typeof data.rawBody === 'string' ? data.rawBody : JSON.stringify(data.body);
const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

const a = Buffer.from(provided, 'utf8');
const b = Buffer.from(expected, 'utf8');
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!valid) {
  // Throwing stops the run and routes it to the error workflow.
  throw new Error('Invalid webhook signature - refusing to process this delivery.');
}
return [{ json: { ...data.body } }];

// Build the owner notification email from the verified payload.
const p = $input.first().json;
const toolName = p.tool && p.tool.name ? p.tool.name : 'a tool';
const borrowerName = p.borrower && p.borrower.name ? p.borrower.name : 'A neighbour';
const ownerEmail = p.owner && p.owner.email ? p.owner.email : '';
if (!ownerEmail) throw new Error('Payload is missing the tool owner email.');
const text = [
  'Hi ' + (p.owner.name || 'there') + ',',
  '',
  borrowerName + ' would like to borrow your "' + toolName + '"',
  'from ' + p.startDate + ' to ' + p.endDate + ' (return by ' + p.endDate + ').',
  p.note ? 'Their note: "' + p.note + '"' : '',
  '',
  'Open LendLoop -> My loans to approve or decline the request.',
  'Event reference: ' + p.eventId,
].filter(Boolean).join('\n');
return [{ json: {
  toEmail: ownerEmail,
  subject: 'LendLoop: new borrow request for "' + toolName + '"',
  text,
  eventId: p.eventId,
  borrowRequestId: p.borrowRequestId,
} }];

const item = $input.first().json;
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const site = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!secret || !site) throw new Error('Configure the Convex site URL and shared secret.');
const rawBody = JSON.stringify({
  eventId: item.eventId,
  kind: 'borrow_request_created',
  borrowRequestId: item.borrowRequestId,
});
const signature = require('crypto').createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
return [{
  json: { rawBody, signature: 'sha256=' + signature, url: site + '/n8n/claim-email' },
  pairedItem: { item: 0 },
}];

// SMTP returns a receipt, so use the linked item for the event identity.
function sign(rawBody) {
  const secret = $env.LENDLOOP_WEBHOOK_SECRET;
  if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set in the n8n environment.');
  return require('crypto').createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');
}
function convexUrl(path) {
  const base = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
  if (!base) throw new Error('CONVEX_SITE_URL is not set in the n8n environment (use the .convex.site URL).');
  return base + path;
}
const item = $('Compose owner email').itemMatching(0).json;
const rawBody = JSON.stringify({
  eventId: item.eventId,
  borrowRequestId: item.borrowRequestId,
  channel: 'email',
});
return [{ json: {
  rawBody,
  signature: 'sha256=' + sign(rawBody),
  url: convexUrl('/n8n/notification-logged'),
}, pairedItem: { item: 0 } }];
